import { currentUser } from "@clerk/nextjs/server";

export type User = {
  id: string;
  email: string;
  name: string;
  createdAt: string;
  // Set once a Clerk account has signed in and been linked to this record.
  clerkId?: string;
};

const users: User[] = [
  { id: "1", email: "ada@example.com", name: "Ada", createdAt: "2026-01-04" },
  { id: "2", email: "grace@example.com", name: "Grace", createdAt: "2026-02-11" },
];

export async function listUsers(): Promise<User[]> {
  return users;
}

export async function getUser(id: string): Promise<User | undefined> {
  return users.find((u) => u.id === id);
}

// Links a Clerk account to an in-memory user record, matching on email so
// someone already seeded above (e.g. "ada@example.com") lands on their
// existing record instead of a duplicate. First-time sign-ins/sign-ups get a
// new record created on the spot.
function linkClerkAccount(clerkId: string, email: string, name: string): User {
  const existing = users.find((u) => u.clerkId === clerkId || u.email === email);
  if (existing) {
    existing.clerkId = clerkId;
    return existing;
  }

  const created: User = {
    id: crypto.randomUUID(),
    email,
    name,
    createdAt: new Date().toISOString().slice(0, 10),
    clerkId,
  };
  users.push(created);
  return created;
}

export async function getCurrentUser(): Promise<User | undefined> {
  const clerkUser = await currentUser();
  if (!clerkUser) return undefined;

  const email =
    clerkUser.primaryEmailAddress?.emailAddress ??
    clerkUser.emailAddresses[0]?.emailAddress ??
    "";
  const name =
    [clerkUser.firstName, clerkUser.lastName].filter(Boolean).join(" ") ||
    email ||
    "Unknown";

  return linkClerkAccount(clerkUser.id, email, name);
}

